import { expect, test } from "@playwright/test";

import { PHOTO_BUFFER } from "../fixtures/media";
import { places } from "../fixtures/visualData";
import { API_URL } from "../support/config";
import { clickMapMarker } from "../support/mapInteractions";
import { mockSharedApi } from "../support/visualApi";

test("memory upload freezes the draft and ignores a duplicate submit while saving", async ({ page }) => {
  let uploadRequests = 0;
  let releaseUpload!: () => void;
  const uploadGate = new Promise<void>((resolve) => {
    releaseUpload = resolve;
  });

  await mockSharedApi(page);
  await page.route(`${API_URL}/api/places/${places[0].id}/memories`, async (route) => {
    if (route.request().method() !== "POST") {
      await route.fulfill({ json: [] });
      return;
    }

    uploadRequests += 1;
    await uploadGate;
    await route.fulfill({
      status: 201,
      json: {
        author_city: null,
        author_name: null,
        caption: "Busy memory",
        created_at: "2026-09-13T00:00:00Z",
        id: "visual-memory-busy",
        memory_text: "Busy memory text",
        place_id: places[0].id,
        status: "pending",
      },
    });
  });

  await page.goto("/");
  await clickMapMarker(page, places[0].title);
  await clickMapMarker(page, `Byłem tutaj: ${places[0].title}`);

  const dialog = page.getByRole("dialog", { name: "Byłem tutaj" });
  await dialog.getByPlaceholder("Wpisz token").fill("claim-token-visual-123456");
  await dialog.getByLabel("Zdjęcie pamiątki").setInputFiles({
    buffer: PHOTO_BUFFER,
    mimeType: "image/jpeg",
    name: "busy-memory.jpg",
  });
  await dialog.getByLabel("Podpis").fill("Busy memory");
  await dialog.getByLabel("Myśl / wspomnienie").fill("Busy memory text");
  await dialog.locator('input[type="checkbox"]').check();

  await dialog.getByRole("button", { name: "Dodaj pamiątkę" }).click();
  await expect.poll(() => uploadRequests).toBe(1);
  await expect(dialog.getByLabel("Zdjęcie pamiątki")).toBeDisabled();
  await expect(dialog.getByLabel("Podpis")).toBeDisabled();
  await expect(dialog.getByLabel("Myśl / wspomnienie")).toBeDisabled();
  await expect(dialog.locator('input[type="checkbox"]')).toBeDisabled();

  await dialog.locator("form.photo-upload").evaluate((form: HTMLFormElement) => form.requestSubmit());
  await page.waitForTimeout(100);
  expect(uploadRequests).toBe(1);

  releaseUpload();
  await expect(page.getByRole("dialog", { name: "Pamiątka trafiła do moderacji" })).toBeVisible();
  expect(uploadRequests).toBe(1);
});
EOF
